_lab_store_draft_media_store(['error'=>UPLOAD_ERR_OK,'tmp_name'=>$png,'size'=>filesize($png),'name'=>'../../ignored.png'],static fn(string $path):bool=>$path===$png,static fn(string $from,string $to):bool=>copy($from,$to),$dir);media_assert((bool)preg_match('#^/public/store-items/drafts/draft-media-[a-f0-9]{32}\.png$#',$ref),'safe server filename ignores client traversal name');media_assert(count(glob($dir.DIRECTORY_SEPARATOR.'*')?:[])===1,'successful upload stores one artifact');try{narrrfs_lab_store_draft_media_store(['error'=>UPLOAD_ERR_NO_FILE,'tmp_name'=>'','size'=>0],static fn():bool=>false,null,$dir);throw new RuntimeException('unexpected');}catch(InvalidArgumentException){}media_assert(true,'malformed file rejects before storage');}finally{foreach(glob($dir.DIRECTORY_SEPARATOR.'*')?:[] as $file)unlink($file);@rmdir($dir);@unlink($png);}$route=file_get_contents(__DIR__.'/api/owner-control/v1/lab-store/draft-media-upload.php');$helper=file_get_contents(__DIR__.'/api/lib/owner-lab-store-draft-media-v1.php');media_assert(is_string($route)&&is_string($helper)&&!str_contains($route,'SQLite3')&&!str_contains($route,'tbl_store_items')&&!str_contains($helper,'tbl_'),'upload has no catalog or database write');$prior===false?putenv($gate):putenv($gate.'='.$prior);echo "PASS: draft media upload contract\n";
